INSERT INTO `day_blocks` (`code`, `ord`, `block_name`, `window_text`, `hours`, `what_happens`) VALUES
  ('DSA', 1, 'DSA', '06:30 to 09:00', 2.5, 'Striver A2Z, in JavaScript. Never skipped, never moved.'),
  ('LEARN', 2, 'LEARN', '09:30 to 12:30', 3, 'One subject per week. Drops to 2.0 from Week 15.'),
  ('BUILD', 3, 'BUILD', '14:00 to 16:00', 2, 'The current project. Code that ships.'),
  ('CLOSE', 4, 'CLOSE', '16:00 to 16:30', 0.5, 'Commit, log.md, tomorrow decided before you stand up.'),
  ('BREAK', 5, 'BREAK', '16:30 to 17:00', 0.5, 'Off the screen. Walk, eat. This break is what makes the money hour possible.'),
  ('MONEY', 6, 'MONEY', '17:00 to 18:00', 1, 'The one extra hour. Outreach, quotes, client delivery. Never study time. Part 17.'),
  ('NIGHT', 7, 'NIGHT RECALL', 'Before sleep', 0.75, 'Anki plus spoken explanation. Four of six nights aloud.')
INSERT INTO `corrections` (`code`, `ord`, `was_wrong`, `actually_true`, `source`, `fix`) VALUES
  ('C01', 1, 'Roadmap starts 3 August 2026, 24 weeks, ends 17 January 2027.', 'You start 28 August 2026. Twenty-five days are gone. 28 Aug 2026 is a Friday; the first full week begins Monday 31 August.', 'Calendar arithmetic, recomputed', 'Rebuilt as 21 weeks plus a 3-day launch block, ending Sunday 24 January 2027.'),
  ('C02', 2, 'Daily Close block is 30 minutes and includes English practice.', 'You removed English from scope.', 'Your instruction, 27 Aug 2026', 'Close block cut to 30 minutes of log and Anki only. The English half-hour moved to DSA.'),
  ('C03', 3, 'A 25-minute English night block on six nights.', 'Removed at your instruction.', 'Your instruction, 27 Aug 2026', 'Replaced by a 45-minute technical Night Recall Block: DSA pattern recall, system design out loud, project walkthrough rehearsal.'),
  ('C04', 4, 'Node.js 24 is the LTS to build on, with no end date given.', 'Node 24 Krypton is Active LTS until 20 October 2026, then Maintenance until end of life on 30 April 2028. Node 26 was released 5 May 2026 and becomes Active LTS on 28 October 2026.', 'nodejs.org previous-releases and release schedule', 'Build on 24. Explicit Node 26 decision point added at Gate 3 in Part 6.'),
  ('C05', 5, 'PostgreSQL 18.4 is current.', 'PostgreSQL 18 was released 25 September 2025. The current minor as verified is 18.6. Version 18 is supported to 14 November 2030.', 'postgresql.org versioning policy', 'Pinned to PostgreSQL 18, minor 18.6 or later.'),
  ('C06', 6, 'Redis 8 is AGPLv3.', 'Since Redis 8.0 in May 2025, Redis Open Source is tri-licensed under RSALv2, SSPLv1 and AGPLv3. Valkey is the Linux Foundation fork of Redis 7.2.4 and is BSD-3-Clause.', 'redis.io and valkey.io licence pages', 'Corrected in Week 14 and in Part 6. One-sentence interview answer added.'),
  ('C07', 7, 'Use AI SDK v5 patterns.', 'AI SDK 7 was released 25 June 2026. It is ESM-only, CommonJS support was removed, and the minimum Node version is 22. Migration from v6 uses npx @ai-sdk/codemod v7.', 'ai-sdk.dev migration guide 7.0 and the Vercel release post', 'Weeks 16 to 19 rewritten against AI SDK 7. Codemod command included.'),
  ('C08', 8, 'pgvector 0.8.3 is the version to install.', 'The exact current patch could not be asserted from a primary source at the verification date. What is verifiable and matters more: vector indexes up to 2,000 dimensions, halfvec to 4,000, bit to 64,000, sparsevec to 1,000 non-zero.', 'github.com/pgvector/pgvector README', 'Patch number removed. Dimension limits stated instead, because that is the constraint that will actually stop you.'),
  ('C09', 9, 'MCP has sessions and an initialize handshake.', 'The current MCP specification revision is 2026-07-28. It removed protocol-level sessions and the Mcp-Session-Id header, and removed the initialize and notifications-initialized handshake. Protocol version and client capabilities now travel in _meta.', 'modelcontextprotocol.io specification 2026-07-28 changelog', 'Week 19 rewritten for a stateless MCP. Server-minted handles replace session state.'),
  ('C10', 10, 'Next.js 15 App Router.', 'Next.js 16 is the Active LTS line, released 21 October 2025. Next.js 15 leaves Maintenance LTS on 21 October 2026, which is inside this roadmap. In 16, Turbopack is default, middleware is renamed proxy with no edge runtime, and PPR is enabled through cacheComponents.', 'nextjs.org support policy and the version 16 upgrade guide', 'Week 10 rewritten for Next.js 16 with the three breaking changes called out.'),
  ('C11', 11, 'Missing Semester lectures cited by number, 2020 edition.', 'The 2026 edition exists and has nine lectures with different names, including Agentic Coding and Code Quality. Lecture numbers do not map across editions.', 'missing.csail.mit.edu/2026', 'Cited by lecture name against the 2026 edition, not by number.'),
  ('C12', 12, 'PGExercises has 71 exercises.', 'The site publishes no headline total. Independent mirrors count 81 across seven categories. The number 71 could not be confirmed.', 'pgexercises.com category pages', 'Stated as roughly 80 across seven categories. Instruction is to finish all categories, not to hit a count.'),
  ('C13', 13, 'Referrals are 6 per cent of applications and 37 per cent of hires.', 'No primary study supports those exact figures. The widely repeated industry figures are roughly 7 per cent and roughly 40 per cent, also without a traceable primary source.', 'No primary source located', 'Marked directional. The instruction stands because the direction is not disputed, but the precision is gone.'),
  ('C14', 14, 'Striver A2Z has 474 problems.', 'Confirmed. 152 easy, 186 medium, 136 hard. Sheet last updated 13 December 2025.', 'takeuforward.org A2Z sheet', 'Kept. Now the basis of the honest 402-hour cost estimate in Part 4.'),
  ('C15', 15, 'Argon2id at m=19456, t=2, p=1.', 'Confirmed exactly against the OWASP Password Storage Cheat Sheet. 19456 KiB is 19 MiB.', 'cheatsheetseries.owasp.org Password Storage Cheat Sheet', 'Kept verbatim. This is a direct interview answer.'),
  ('C16', 16, 'Contextual retrieval cuts failures by 49 per cent.', 'Confirmed and now stated in full. Top-20 retrieval failure fell from 5.7 to 3.7 per cent with contextual embeddings, a 35 per cent reduction; to 2.9 per cent adding contextual BM25, a 49 per cent reduction; to 1.9 per cent adding reranking, a 67 per cent reduction.', 'anthropic.com/engineering/contextual-retrieval', 'Expanded to all three stages in Week 17.'),
  ('C17', 17, 'OWASP Top 10:2025 maps 248 CWEs.', 'The 2025 list is confirmed as the eighth installment with the new A03 Software Supply Chain Failures and the new A10 Mishandling of Exceptional Conditions replacing SSRF. The figure of 248 CWEs could not be verified.', 'owasp.org/Top10/2025', 'Category names and order kept. The CWE count removed.'),
  ('C18', 18, 'Use Pramp for mock interviews.', 'Pramp was acquired by Exponent in November 2021 and folded into Exponent Practice in July 2024. Pramp links redirect.', 'tryexponent.com/practice', 'Replaced throughout with Exponent Practice.'),
  ('C19', 19, 'Read The Copenhagen Book.', 'The Copenhagen Book was renamed and moved. It is now The Auth Book at auth.pilcrowonpaper.com, announced 3 June 2026. The old domain is archived.', 'auth.pilcrowonpaper.com', 'Replaced in Week 11 and in the resource library.'),
  ('C20', 20, 'React 18 patterns, memoise aggressively.', 'React 19.2 shipped 1 October 2025 and React Compiler 1.0 became stable on 7 October 2025. Most manual useMemo and useCallback advice predates the compiler.', 'react.dev blog and the React Compiler documentation', 'Weeks 5 and 6 updated. Hand-memoisation is now an explicit anti-pattern in this plan.'),
  ('C21', 21, 'Configure Tailwind in tailwind.config.js.', 'Tailwind v4 is CSS-first. There is no tailwind.config.js by default; theme tokens live in an @theme block. A JS config can still be re-linked with @config, but that is a compatibility path.', 'tailwindcss.com/docs', 'Week 6 rewritten for v4. The silent-failure trap is called out explicitly.'),
  ('C22', 22, 'Forward Deployed Engineer roles pay 15 to 25 lakh at entry in India.', 'TeamLease Digital data reported in July 2026 puts FDE entry at 10 to 12 lakh, mid-level at 25 to 50 lakh and senior at 50 to 80 lakh and above.', 'TeamLease Digital, reported in The Hindu, July 2026', 'Part 12 corrected downward. Entry expectations are now honest.'),
  ('C23', 23, 'The Indian AI job market is booming.', 'Specific and current: Naukri JobSpeak for June 2026 showed AI roles in IT up 16 per cent year on year while overall IT hiring fell 3 per cent. July 2026 showed IT up 6 per cent and AI jobs up 33 per cent. February 2026 showed the 20-plus lakh fresher band up 30 per cent.', 'Naukri JobSpeak, reported by Reuters 3 July 2026', 'Part 12 now carries dated figures instead of an adjective.'),
  ('C24', 24, 'Week 14 is security. Week 13 is testing.', 'In v3 the Week 14 link list was testing-only and duplicated Week 13. The security week had no security links.', 'Internal contradiction in the source document', 'Fixed. Week 13 is security with the 2025 list. Week 14 is Docker, Compose and Redis. No duplication.'),
  ('C25', 25, 'Cover says 474 problems and 1,224 hours; body says 398 problems and 1,152 hours.', 'Three different totals appeared in one document. None of them reconciled.', 'Internal contradiction in the source document', 'Every total in this document is computed by script from one table. 415 problems by 24 January 2027, 1,198.5 hours including the night block.')
INSERT INTO `subjects` (`ord`, `subject`, `when_text`, `hours_text`) VALUES
  (1, 'DSA', 'Every morning, all 21 weeks', '2.5 per day, 315 total'),
  (2, 'Web development', 'Weeks 1 to 15', 'LEARN and BUILD blocks'),
  (3, 'Applied AI', 'Weeks 16 to 19', 'LEARN and BUILD blocks')
INSERT INTO `launch_days` (`cal_date`, `ord`, `day_name`, `work`) VALUES
  ('2026-08-28', 1, 'Friday', 'Decommission the old AWS EC2 box that is still billing. Document all 8 TLS certificates and their renewal dates. Create the four project repositories: itc-reclaim, itc-reclaim-api, itc-reclaim-ops, tender-fit.'),
  ('2026-08-29', 2, 'Saturday', 'Move local PostgreSQL 16 to 18. Verify pg_dump and restore both directions. Install the three Anki decks: DSA Patterns, System and Stack, Interview Answers. Set up log.md, versions.md, failed-twice.md.'),
  ('2026-08-30', 3, 'Sunday', 'Striver A2Z account and tracker. First 6 problems to prove the morning block works. Read the whole of Part 1 and Part 4 of this document. Decide nothing else after this point.')
INSERT INTO `phases` (`code`, `ord`, `name`, `week_from`, `week_to`, `blurb`) VALUES
  ('A', 1, 'Foundation', 1, 4, 'Language, git, the browser, the wire. No framework touches the machine.'),
  ('B', 2, 'Interface', 5, 7, 'React, Tailwind v4, TypeScript. Gate 1 lands at the end of Week 5.'),
  ('C', 3, 'Backend', 8, 11, 'Node, PostgreSQL 18, Next.js 16, auth you wrote with your own hands. Gate 2.'),
  ('D', 4, 'Production', 12, 15, 'Tests, CI, OWASP 2025, Docker, Redis, queues, performance. Gate 3.'),
  ('E', 5, 'Applied AI', 16, 19, 'LLM plumbing, RAG with real numbers, evals, agents, one MCP server.'),
  ('F', 6, 'Conversion', 20, 21, 'Mocks, revision, then volume applications. Gate 4 closes the plan.')
INSERT INTO `gates` (`no`, `week_n`, `gate_date`, `condition_text`) VALUES
  (1, 5, '2026-10-04', 'Project 1 live on your own domain over HTTPS'),
  (2, 11, '2026-11-15', 'Auth you wrote yourself, plus one WebSocket feature'),
  (3, 15, '2026-12-13', 'Project 3 operable, and applications begin'),
  (4, 21, '2027-01-24', 'Project 4 live, 100 applications sent')
INSERT INTO `projects` (`id`, `code`, `name`, `repo`, `week_from`, `week_to`, `description`) VALUES
  (1, 'P1', 'ITC Reclaim', 'itc-reclaim', 3, 7, 'GST input tax credit reconciliation. Upload GSTR-2B and the purchase register, match them, show what credit is unclaimed. The gap between those two files is money the business is entitled to claim and has not. Finding it by hand takes a day.'),
  (2, 'P2', 'ITC Reclaim API', 'itc-reclaim-api', 8, 11, 'The same problem as a real backend. Multi-tenant: organisations, users and roles. Auth you wrote yourself. An audit log of who changed what, and when. One WebSocket feature.'),
  (3, 'P3', 'ITC Reclaim Ops', 'itc-reclaim-ops', 12, 15, 'The same system made operable. Tests, CI that blocks on red, containers, queues, logs, metrics, and a rollback you have actually executed once.'),
  (4, 'P4', 'Tender Fit', 'tender-fit', 16, 19, 'Applied AI. Ingest a government tender document, retrieve against the company profile with hybrid search and citations, score the fit, explain the gaps. Published Ragas numbers and an honest failure mode section.')
INSERT INTO `readme_sections` (`id`, `ord`, `title`) VALUES
  (1, 1, 'The problem, in one paragraph, with a rupee figure'),
  (2, 2, 'A screenshot or a 30 second GIF above the fold'),
  (3, 3, 'Live URL and the repo'),
  (4, 4, 'The stack, with versions'),
  (5, 5, 'Architecture: one diagram, drawn by you'),
  (6, 6, 'How to run it locally, tested from a clean clone'),
  (7, 7, 'What is measured: latency, cost, coverage, or accuracy'),
  (8, 8, 'What does not work yet, stated plainly'),
  (9, 9, 'What you would do next with two more weeks')
INSERT INTO `stack_versions` (`id`, `tech`, `version`, `status`, `why`) VALUES
  (1, 'Node.js', '24 LTS (Krypton)', 'Active LTS to 20 Oct 2026', 'Maintenance after that, end of life 30 Apr 2028. Node 26 goes Active LTS on 28 Oct 2026.'),
  (2, 'Package manager', 'pnpm', 'Stable', 'Faster installs, strict node_modules, better monorepo story than npm.'),
  (3, 'TypeScript', 'Latest stable', 'Stable', 'strict, noUncheckedIndexedAccess and exactOptionalPropertyTypes on from file one.'),
  (4, 'React', '19.2', 'Current', 'React Compiler 1.0 stable since 7 Oct 2025. Do not hand-memoise.'),
  (5, 'Next.js', '16.x', 'Active LTS', 'Turbopack default. middleware is now proxy. PPR via cacheComponents.'),
  (6, 'Tailwind CSS', 'v4', 'Current', 'CSS-first. @theme block. No tailwind.config.js by default.'),
  (7, 'PostgreSQL', '18 (18.6+)', 'Current, supported to 14 Nov 2030', 'Async I/O, skip scan, uuidv7(), virtual generated columns.'),
  (8, 'ORM', 'Prisma or Drizzle', 'Pick one, stay', 'Migrations committed to the repository and run in CI.'),
  (9, 'Validation', 'zod', 'Stable', 'Parse at every boundary. Never trust an input you did not validate.'),
  (10, 'Auth', 'Hand-written sessions', 'By design', 'Argon2id m=19456, t=2, p=1. SHA-256 hashed session tokens.'),
  (11, 'Cache and queue', 'Redis 8 or Valkey', 'Current', 'Redis 8 is tri-licensed RSALv2 / SSPLv1 / AGPLv3. Valkey is BSD-3-Clause.'),
  (12, 'Queue library', 'BullMQ', 'Stable', 'Idempotent handlers. Dead letter queue. Retries with backoff.'),
  (13, 'Testing', 'Vitest, Testing Library, MSW, Playwright', 'Stable', 'Twelve good tests beat sixty generated ones.'),
  (14, 'Containers', 'Docker + Compose v2', 'Current', 'Compose v2 is a space, not a hyphen. Multi-stage, non-root, healthcheck.'),
  (15, 'CI', 'GitHub Actions', 'Stable', 'Pinned action SHAs. Lockfile audit. Merge blocked on red.'),
  (16, 'AI SDK', 'AI SDK 7', 'Released 25 Jun 2026', 'ESM-only. CommonJS removed. Node 22 minimum. Codemod: npx @ai-sdk/codemod v7.'),
  (17, 'Vector store', 'pgvector on PostgreSQL 18', 'Current', 'vector indexes to 2,000 dims, halfvec to 4,000. Use halfvec for 3,072-dim embeddings.'),
  (18, 'MCP', 'Specification 2026-07-28', 'Current', 'Stateless. No Mcp-Session-Id. No initialize handshake. Capabilities in _meta.')
INSERT INTO `breaks` (`id`, `if_you_do`, `what_happens`) VALUES
  (1, 'You follow a Tailwind v3 tutorial.', 'You write a tailwind.config.js that is silently ignored. No error. You lose a day.'),
  (2, 'You follow a Next.js 15 tutorial.', 'Your middleware file does nothing under the new name, and the caching model you learned is wrong.'),
  (3, 'You install AI SDK 7 and use require.', 'It fails immediately. v7 is ESM-only and CommonJS was removed.'),
  (4, 'You use a 3,072-dimension embedding with the vector type.', 'The index will not build. The indexable ceiling for vector is 2,000. Use halfvec.'),
  (5, 'You read an MCP guide from 2025.', 'You build session handling that the 2026-07-28 specification deleted.'),
  (6, 'You quote OWASP A10 as SSRF.', 'You are citing the 2021 list. In 2025 A10 is Mishandling of Exceptional Conditions.'),
  (7, 'You run docker-compose with a hyphen.', 'Command not found. Compose v2 is docker compose, with a space.'),
  (8, 'You hand-memoise React components.', 'You are fighting React Compiler 1.0 and adding noise an interviewer will notice.'),
  (9, 'You stay on Node 20 or below.', 'AI SDK 7 will not install. The minimum is Node 22.'),
  (10, 'You learn on PostgreSQL 16 then deploy on 18.', 'Generated columns and I/O behaviour differ. Move your local instance to 18 in Week 9.'),
  (11, 'You cite Pramp or The Copenhagen Book.', 'Both moved. It reads as material you copied rather than material you used.')
