INSERT INTO `resources` (`id`, `category_no`, `ord`, `url`, `label`, `why`, `cost`, `weeks_csv`) VALUES
  (1, 1, 1, 'https://javascript.info', 'javascript.info', 'The single best free JavaScript resource in existence. Chapters 4 to 12 are the spine of Weeks 1, 3 and 4.', 'Free', ''),
  (2, 1, 2, 'https://developer.mozilla.org/en-US/docs/Web/JavaScript', 'developer.mozilla.org/en-US/docs/Web/JavaScript', 'Reference, not tutorial. Use it to check, not to learn.', 'Free', ''),
  (3, 1, 3, 'https://eloquentjavascript.net', 'eloquentjavascript.net', 'Read chapters 5, 6, 11 and 18 only. The rest overlaps javascript.info.', 'Free', ''),
  (4, 1, 4, 'https://github.com/getify/You-Dont-Know-JS', 'github.com/getify/You-Dont-Know-JS', 'Scope and Closures, plus this and Object Prototypes. Reference depth.', 'Free', ''),
  (5, 1, 5, 'https://latentflip.com/loupe', 'latentflip.com/loupe', 'Event loop, visualised. Fifteen minutes, permanent payoff.', 'Free', '4'),
  (6, 1, 6, 'https://jsv9000.app', 'jsv9000.app', 'Microtask against macrotask queue, visualised. Better than loupe for promises.', 'Free', '4'),
  (7, 2, 1, 'https://git-scm.com/book/en/v2', 'git-scm.com/book/en/v2', 'Pro Git. Chapters 2 and 3 in Week 1, chapter 7 when you need it.', 'Free', '1'),
  (8, 2, 2, 'https://learngitbranching.js.org', 'learngitbranching.js.org', 'All main and remote levels. The only way rebase becomes intuitive.', 'Free', '1'),
  (9, 2, 3, 'https://missing.csail.mit.edu/2026', 'missing.csail.mit.edu/2026', 'MIT. Shell, Command-line Environment, Version Control, Debugging and Profiling.', 'Free', '1'),
  (10, 2, 4, 'https://wizardzines.com', 'wizardzines.com', 'Julia Evans. The comics on DNS, HTTP and containers are genuinely the fastest path.', 'Free / paid zines', '2'),
  (11, 2, 5, 'https://linuxjourney.com', 'linuxjourney.com', 'Gap-fill only. Occasionally offline; a LabEx mirror exists.', 'Free', '2'),
  (12, 2, 6, 'https://nginx.org/en/docs', 'nginx.org/en/docs', 'Server blocks, proxy_pass, TLS termination. You already run this.', 'Free', '2'),
  (13, 3, 1, 'https://flexboxfroggy.com', 'flexboxfroggy.com', 'All 24 levels in Week 2. Then rebuild the layouts without the game.', 'Free', '2'),
  (14, 3, 2, 'https://cssgridgarden.com', 'cssgridgarden.com', 'All 28 levels. Same rule: rebuild afterwards.', 'Free', '2'),
  (15, 3, 3, 'https://web.dev/learn/css', 'web.dev/learn/css', 'Stacking contexts, z-index, overflow, inheritance. The parts games skip.', 'Free', '2'),
  (16, 3, 4, 'https://web.dev/learn/html', 'web.dev/learn/html', 'Semantics done properly, which is most of accessibility for free.', 'Free', '2'),
  (17, 3, 5, 'https://web.dev/learn/accessibility', 'web.dev/learn/accessibility', 'One pass in Week 6. Labels, focus order, keyboard, contrast.', 'Free', '6'),
  (18, 3, 6, 'https://joshwcomeau.com', 'joshwcomeau.com', 'The CSS articles are the clearest explanations of layout on the internet.', 'Free articles', '2'),
  (19, 4, 1, 'https://react.dev/learn', 'react.dev/learn', 'Current source of truth. Read alongside Full Stack Open, not after it.', 'Free', '5'),
  (20, 4, 2, 'https://react.dev/learn/you-might-not-need-an-effect', 'react.dev/learn/you-might-not-need-an-effect', 'Read twice in Week 5. Most junior React code is effects that should not exist.', 'Free', '5'),
  (21, 4, 3, 'https://react.dev/learn/escape-hatches', 'react.dev/learn/escape-hatches', 'Week 6 in full. Refs, effect lifecycle, removing dependencies, custom hooks.', 'Free', '6'),
  (22, 4, 4, 'https://react.dev/learn/react-compiler', 'react.dev/learn/react-compiler', 'Compiler 1.0 stable since Oct 2025. Read before you write any memo.', 'Free', '6'),
  (23, 4, 5, 'https://fullstackopen.com/en', 'fullstackopen.com/en', 'University of Helsinki. Parts 0 to 2 in Week 5. Continuously updated, no yearly versions.', 'Free', '5'),
  (24, 4, 6, 'https://overreacted.io', 'overreacted.io', 'Dan Abramov. Read when a React behaviour surprises you.', 'Free', '5'),
  (25, 5, 1, 'https://typescriptlang.org/docs/handbook/intro.html', 'typescriptlang.org/docs/handbook/intro.html', 'Start to finish in Week 7. Not a skim.', 'Free', '7'),
  (26, 5, 2, 'https://totaltypescript.com/tutorials', 'totaltypescript.com/tutorials', 'Matt Pocock. The free tutorials cover generics and narrowing better than the handbook.', 'Free tier', '7'),
  (27, 5, 3, 'https://github.com/type-challenges/type-challenges', 'github.com/type-challenges/type-challenges', 'Easy tier only. Do not rabbit-hole into medium.', 'Free', '7'),
  (28, 5, 4, 'https://typescriptlang.org/tsconfig', 'typescriptlang.org/tsconfig', 'Every flag explained. Turn on strict and noUncheckedIndexedAccess.', 'Free', '7'),
  (29, 5, 5, 'https://typescriptlang.org/play', 'typescriptlang.org/play', 'Test a type theory in ten seconds instead of ten minutes.', 'Free', '7'),
  (30, 6, 1, 'https://nextjs.org/learn', 'nextjs.org/learn', 'The official course. Week 10, end to end.', 'Free', '10'),
  (31, 6, 2, 'https://nextjs.org/docs/app/guides/upgrading/version-16', 'nextjs.org/docs/app/guides/upgrading/version-16', 'Read even though you start on 16. It names every breaking change.', 'Free', '10'),
  (32, 6, 3, 'https://nextjs.org/support-policy', 'nextjs.org/support-policy', 'Confirms 16 is Active LTS and 15 leaves maintenance on 21 Oct 2026.', 'Free', '10'),
  (33, 6, 4, 'https://tailwindcss.com/docs', 'tailwindcss.com/docs', 'v4 CSS-first. @theme, @utility, @variant. Ignore every v3 tutorial.', 'Free', '6'),
  (34, 7, 1, 'https://nodejs.org/en/learn', 'nodejs.org/en/learn', 'Modules, event loop, streams, file system. Week 8.', 'Free', '8'),
  (35, 7, 2, 'https://nodejs.org/en/about/previous-releases', 'nodejs.org/en/about/previous-releases', 'The release schedule table. Check it at Gate 3 for the Node 26 decision.', 'Free', ''),
  (36, 7, 3, 'https://expressjs.com', 'expressjs.com', 'Routing, middleware order, error middleware. Small surface, learn all of it.', 'Free', '8'),
  (37, 7, 4, 'https://zod.dev', 'zod.dev', 'Parse, do not validate. Every boundary, every time.', 'Free', '8'),
  (38, 7, 5, 'https://github.com/goldbergyoni/nodebestpractices', 'github.com/goldbergyoni/nodebestpractices', 'Read end to end once in Week 8, then use as a checklist.', 'Free', '8'),
  (39, 7, 6, 'https://docs.bullmq.io', 'docs.bullmq.io', 'Week 15. Workers, retries, backoff, dead letter queues.', 'Free', '15'),
  (40, 8, 1, 'https://pgexercises.com', 'pgexercises.com', 'All seven categories, roughly 80 exercises. Week 9.', 'Free', '9'),
  (41, 8, 2, 'https://postgresql.org/docs/current/tutorial.html', 'postgresql.org/docs/current/tutorial.html', 'The official tutorial, then the parts of the manual you need.', 'Free', '9'),
