INSERT INTO `course_rulings` (`id`, `course`, `ruling`) VALUES
  (1, '100xSchool Combined Bootcamp', 'Bundle wrapper. Never open it as a course.'),
  (2, 'Web Dev + DevOps Bootcamp', 'Lookup only. 13 of its 16 web topics map onto Weeks 1 to 15.'),
  (3, 'DSA Bootcamp', 'Keep the topic order as a checklist. Skip the videos: it is C++.'),
  (4, 'AI and ML Bootcamp', 'Optional Sunday or night viewing for intuition. Never in place of the Week 16 to 19 builds. Skip anything on training or fine tuning models.'),
  (5, 'Web3 Bootcamp', 'Do not open before Gate 4. Zero overlap with all seven roles in Part 12.')
