INSERT INTO `video_rules` (`id`, `ord`, `rule`) VALUES
  (1, 1, 'Open the week in Part 4. Read the LEARN topic and the BUILD task.'),
  (2, 2, '**Try to build first.** Part 11.2.'),
  (3, 3, 'Stuck on one specific concept? Only then search the bootcamp for that one video. Watch at 1.5x or 2x.'),
  (4, 4, 'Close it. Return to the code.'),
  (5, 5, '**Hard cap: 30 minutes of video per day, taken from inside the LEARN block, never added on top of it.**'),
  (6, 6, 'Never watch a section end to end. Never try to complete a course.')
INSERT INTO `falsifier` (`id`, `ord`, `text`) VALUES
  (1, 1, 'If your video count is still near zero **and** DSA cumulative is at or above 96, the deferral was correct. Stop feeling guilty about the 0 per cent.'),
  (2, 2, 'If your video count has climbed **and** DSA cumulative is below 96, the courses are stealing roadmap hours. Close them and do not reopen before Gate 4.')
INSERT INTO `night_segments` (`id`, `ord`, `segment`, `minutes`, `detail`) VALUES
  (1, 1, 'Anki, all three decks', 20, 'DSA Patterns, System and Stack, Interview Answers. Zero overdue is the only acceptable state.'),
  (2, 2, 'Spoken explanation', 15, 'Explain the day out loud, to the wall, no notes. Four nights of six must be spoken, not read.'),
  (3, 3, 'Tomorrow, decided', 10, 'Write the first DSA problem and the first build task for tomorrow. Never decide this in the morning.')
