INSERT INTO `focus_rules` (`id`, `ord`, `rule`) VALUES
  (1, 1, 'One tab of documentation. One editor. Nothing else on the screen.'),
  (2, 2, 'Phone in another room, not face down on the desk.'),
  (3, 3, 'The block starts on the clock, not when you feel ready.'),
  (4, 4, 'If you are stuck for 30 minutes, write down the question, then move. Return at CLOSE.'),
  (5, 5, 'No refactoring during BUILD. Ugly and shipped beats elegant and unfinished.'),
  (6, 6, 'No new tool, library or framework enters the plan mid-week.'),
  (7, 7, 'The day ends at 16:30 whether or not it went well.')
INSERT INTO `honesty_tests` (`id`, `ord`, `question`) VALUES
  (1, 1, 'Can you explain it back, out loud, with no notes?'),
  (2, 2, 'Can you generate a new practice case yourself rather than recognising one?'),
  (3, 3, 'Is Anki at zero overdue?'),
  (4, 4, 'Did the thing you built this week actually run for someone other than you?')
INSERT INTO `roles` (`code`, `name`, `short_name`, `entry_band`, `band_low_lakh`, `band_high_lakh`, `ceiling`, `verdict`, `what_they_test`, `which_project`, `rank_order`) VALUES
  ('AAE', 'Applied AI Engineer', 'Applied AI Engineer', 'Rs 8 to 15 lakh', 8, 15, 'Rs 40 lakh and above', 'PRIMARY TARGET. Best fit for what this roadmap builds.', 'RAG architecture, retrieval quality, evaluation methodology, cost per query, prompt injection defence, agent design and termination.', 'Project 4 (Tender Fit) end to end, with published Ragas numbers and an honest failure-mode section.', 1),
  ('FDE', 'Forward Deployed Engineer', 'Forward Deployed Engineer', 'Rs 10 to 12 lakh', 10, 12, 'Rs 50 to 80 lakh and above at senior level', 'STRONG SECOND. Highest ceiling on this list. Rewards exactly the customer-problem instinct your projects show.', 'Case studies rather than algorithms. Scoping an ambiguous customer problem, shipping under constraint, talking to non-engineers, integration reality.', 'ITC Reclaim across Projects 1 to 3. It is a real business problem with a measurable rupee outcome.', 2),
  ('FS', 'Full Stack Engineer (AI-adjacent)', 'Full Stack Engineer', 'Rs 6 to 12 lakh', 6, 12, 'Rs 35 lakh and above', 'STRONG. The widest volume of postings in India, so the highest number of shots.', 'React, Next.js, Node, PostgreSQL, auth, deployment, and whether you can debug production.', 'Project 3, containerised on your own server, with CI, tests, logs and a rollback you have executed.', 3),
  ('BE', 'Backend Engineer', 'Backend Engineer', 'Rs 6 to 12 lakh', 6, 12, 'Rs 40 lakh and above', 'STRONG. Weeks 8 to 15 are aimed squarely here.', 'API design, schema design, indexes, transactions, queues, idempotency, observability, one system design round.', 'Project 2 and Project 3. The EXPLAIN ANALYZE before-and-after number carries this interview.', 4),
  ('ASE', 'AI Solutions Engineer', 'AI Solutions Engineer', 'Rs 8 to 14 lakh', 8, 14, 'Rs 35 lakh and above', 'GOOD. A hybrid of technical depth and customer contact.', 'Demonstrating a system live, scoping a proof of concept, integration questions, and honesty about limits.', 'The four-minute Project 4 demo recorded in Week 19, plus the ITC Reclaim business framing.', 5),
  ('PLAT', 'Platform or DevOps-adjacent Engineer', 'Platform / DevOps-adjacent', 'Rs 6 to 11 lakh', 6, 11, 'Rs 30 lakh and above', 'POSSIBLE. You already run more infrastructure than most juniors, but this roadmap does not target it.', 'Linux, containers, CI, TLS, reverse proxies, monitoring, incident response.', 'Your existing Oracle Cloud VPS with 8 TLS certificates, plus the Week 14 container work.', 6),
  ('DE', 'Data Engineer', 'Data Engineer', 'Rs 6 to 12 lakh', 6, 12, 'Rs 35 lakh and above', 'WEAKEST FIT. Only if a posting emphasises pipelines over models. Do not lead with it.', 'SQL depth, pipeline design, orchestration, data quality.', 'The ingest and reconciliation pipeline in Projects 1 to 3, plus Working Sundays 4 and 5.', 7)
INSERT INTO `roles_early` (`id`, `code`, `role`, `earliest_text`, `earliest_week`, `earliest_date`, `entry_band`, `band_low_lakh`, `band_high_lakh`, `verdict`) VALUES
  (1, 'WEB', 'Web Developer, template and WordPress sites', 'today, 28 Aug 2026', 0, '2026-08-28', 'Rs 1.8 to 4 lakh', 1.8, 4, 'You can already do this by prompting. It teaches you almost nothing and it is very hard to leave'),
  (2, 'SUP', 'Technical Support or Implementation Engineer', 'Week 3, 20 Sep 2026', 3, '2026-09-20', 'Rs 3 to 6 lakh', 3, 6, 'Real product exposure, almost no growth in code. A trap after twelve months'),
  (3, 'FE', 'Frontend Developer', 'Week 7, 18 Oct 2026', 7, '2026-10-18', 'Rs 3.5 to 7 lakh', 3.5, 7, 'Eligible, and underselling yourself by two bands. Part 13 already says so'),
  (4, 'AUTO', 'Automation Engineer, n8n and integrations', 'Week 8, 25 Oct 2026', 8, '2026-10-25', 'Rs 3 to 7 lakh', 3, 7, 'The best of the early exits. It is what offer O4 already sells, so you would be paid for work you can already do'),
  (5, 'JRT', 'Junior or Trainee Software Engineer, service company', 'Week 9, 1 Nov 2026', 9, '2026-11-01', 'Rs 3.5 to 6 lakh', 3.5, 6, '204 problems clears TCS, Infosys, Wipro, Cognizant and Accenture screens. Steady, slow, safe, capped'),
  (6, 'INT', 'Integration or Solutions Engineer, junior', 'Week 11, 15 Nov 2026', 11, '2026-11-15', 'Rs 5 to 9 lakh', 5, 9, 'Good pay, real client contact, and the natural feeder into FDE later'),
  (7, 'QA', 'QA Automation Engineer', 'Week 12, 22 Nov 2026', 12, '2026-11-22', 'Rs 4 to 8 lakh', 4, 8, 'Your Week 12 testing work qualifies you. Pays acceptably. Moving into development from here is harder than it sounds'),
  (8, 'DEVREL', 'Technical Writer or Developer Relations associate', 'Week 13, 29 Nov 2026', 13, '2026-11-29', 'Rs 4 to 9 lakh', 4, 9, 'Your 46 repositories and log.md are the portfolio. Underrated, and genuinely open to you'),
  (9, 'PROMPT', 'AI Automation or Prompt Engineer', 'Week 16, 20 Dec 2026', 16, '2026-12-20', 'Rs 5 to 10 lakh', 5, 10, 'Real demand, unstable title. Take it only if the job description includes writing code')
