INSERT INTO `eligibility_dsa` (`id`, `ord`, `problems`, `reached_about`, `gets_you_past`, `does_not_open`) VALUES
  (1, 1, 25, 'Week 1, 6 Sep 2026', 'nothing', 'everything'),
  (2, 2, 50, 'Week 2, 13 Sep 2026', 'a warm up question in a friendly screen', 'every real screen'),
  (3, 3, 75, 'Week 3, 20 Sep 2026', 'nothing on its own', 'every real screen'),
  (4, 4, 100, 'early Week 5, about 1 Oct 2026', 'the first automated coding screens at small companies, and most internship filters', 'any product company loop, and every single role in Part 12'),
  (5, 5, 125, 'Week 6, about 8 Oct 2026', 'basic service company screens', 'service company loops, which need breadth you do not have yet'),
  (6, 6, 150, 'Week 7, about 15 Oct 2026', 'basic service screens comfortably. With JavaScript and TypeScript this is the FE threshold', 'product screens, and anything backend'),
  (7, 7, 175, 'Week 8, about 24 Oct 2026', 'the same class of screen with a safer margin', 'product screens'),
  (8, 8, 200, 'Week 9, 1 Nov 2026', 'TCS, Infosys, Wipro, Cognizant and Accenture loops. The real service company threshold', 'mid tier product screens'),
  (9, 9, 250, 'Week 12, about 20 Nov 2026', 'mid tier product screens begin to open', 'top tier product loops'),
  (10, 10, 300, 'Week 14, 6 Dec 2026', 'mid tier product company screens, confidently', 'top tier product loops'),
  (11, 11, 350, 'Week 17, about 26 Dec 2026', 'most product company loops below the top tier', 'the top tier, which needs 450 plus and a different kind of preparation'),
  (12, 12, 415, 'Gate 4, 24 Jan 2027', 'most product company loops, including good product companies', 'nothing that matters for your seven target roles'),
  (13, 13, 474, 'February 2027', 'the sheet is complete', 'past here the returns fall sharply. Move the hours to mock interviews')
INSERT INTO `fast_exits` (`id`, `exit_no`, `exit_label`, `exit_date`, `exit_week`, `roles_available`, `band`, `what_you_give_up`, `verdict`, `cost_note`, `before_gate3`) VALUES
  (1, 1, 'Exit 1', '2026-10-18', 7, 'FE or SUP', 'Rs 3.5 to 7 lakh', 'Node, PostgreSQL, auth, Docker, security, queues and the entire AI layer. You cap as a frontend or support person for two to three years, and the New Zealand track in Part 16 needs backend depth you would never build', 'Only if the household cannot eat. It costs roughly Rs 4 lakh a year for three years, and adds about two years to the New Zealand timeline', 'It costs roughly Rs 4 lakh a year for three years, and adds about two years to the New Zealand timeline', 1),
  (2, 2, 'Exit 2', '2026-11-15', 11, 'Junior FS, junior BE or INT', 'Rs 5 to 9 lakh', 'Docker, CI, security, queues, tuning and the entire AI layer. You would be a junior who cannot operate what he builds', 'Defensible only if the money hour has completely failed by 15 November. It costs about Rs 3 lakh a year, and the 25 to 40 per cent AI premium permanently', 'It costs about Rs 3 lakh a year, and the 25 to 40 per cent AI premium permanently', 1),
  (3, 3, 'Exit 3', '2026-12-13', 15, 'FS, BE or PLAT at full strength', 'Rs 6 to 12 lakh', 'only the AI layer, which is six weeks of work', 'This is the sane exit, and it is not really an exit at all. Part 13 already tells you to start applying on this exact date', NULL, 0),
  (4, 4, 'Exit 4', '2027-01-10', 19, 'all sixteen roles', 'Rs 8 to 15 lakh', 'two weeks of mock interviews and Project 4 polish', 'Take any good offer that arrives here. Do not wait until 24 January to accept something already on the table', NULL, 0)
INSERT INTO `skill_combos` (`id`, `sort_order`, `stack_held`, `dsa_needed_text`, `dsa_needed`, `roles_unlocked_text`, `roles_unlocked_codes`, `band`, `interview_you_face`) VALUES
  (1, 1, 'Prompting only, no unaided code. Where you are tonight', '0', 0, 'WEB', '[\"WEB\"]', 'Rs 1.8 to 4 lakh', 'Show a site, quote a price. No technical interview at all'),
  (2, 2, 'JavaScript written unaided, plus Git', '100', 100, 'WEB, SUP', '[\"WEB\",\"SUP\"]', 'Rs 3 to 6 lakh', 'One easy coding question, mostly behavioural'),
  (3, 3, 'The above plus HTTP, CORS and async', '150', 150, 'WEB, SUP, and AUTO screens', '[\"WEB\",\"SUP\",\"AUTO\"]', 'Rs 3 to 7 lakh', 'Two easy questions and one debugging task'),
  (4, 4, 'The above plus React 19 and Tailwind v4', '150', 150, 'FE', '[\"FE\"]', 'Rs 3.5 to 7 lakh', 'A React take home, one easy problem, component design'),
  (5, 5, 'The above plus TypeScript strict', '162, and JRT opens at 204', 162, 'FE properly, JRT', '[\"FE\",\"JRT\"]', 'Rs 4 to 7 lakh', 'A typed take home, one generics question, one medium problem'),
  (6, 6, 'The above plus Node, Express and PostgreSQL', '204', 204, 'FS junior, BE junior, JRT, AUTO', '[\"FS\",\"BE\",\"AUTO\",\"JRT\"]', 'Rs 5 to 9 lakh', 'API design, schema design, two medium problems'),
  (7, 7, 'The above plus your own auth, Docker, CI, tests, OWASP, queues and EXPLAIN ANALYZE', '318', 318, 'FS, BE, PLAT, QA, INT and DEVREL, all at full strength', '[\"FS\",\"BE\",\"PLAT\",\"INT\",\"QA\",\"DEVREL\"]', 'Rs 6 to 12 lakh', 'One system design round, one security round, three medium problems and one hard'),
  (8, 8, 'The above plus RAG, Ragas, injection defence, agents and one MCP server', '415', 415, 'all sixteen, including AAE and FDE', '[\"AAE\",\"FDE\",\"FS\",\"BE\",\"ASE\",\"PLAT\",\"DE\",\"WEB\",\"SUP\",\"FE\",\"AUTO\",\"JRT\",\"INT\",\"QA\",\"DEVREL\",\"PROMPT\"]', 'Rs 8 to 15 lakh, FDE above it', 'RAG architecture, retrieval quality, cost per query, agent termination, one hard problem')
INSERT INTO `break_plan` (`id`, `ord`, `text`) VALUES
  (1, 1, 'Break it for a written offer at Rs 8 lakh or above, in any week, at any point. Take it and finish the roadmap in the evenings.'),
  (2, 2, 'Break it for any offer at all if the household genuinely cannot manage. Survival outranks optimisation, and there is no shame anywhere in that sentence.'),
  (3, 3, 'Do not break it for an offer below Rs 6 lakh before 13 December 2026.'),
  (4, 4, 'Do not break it for WEB or SUP at any time unless the line above applies, because those two roles are the hardest of all to leave.'),
  (5, 5, 'Never break it for a role that does not let you write code on most days.'),
  (6, 6, 'If you do break it, the roadmap does not stop. Part 15 already describes the employed weekday shape. The gates move to weekends and the AI layer takes twelve weeks instead of six.')
INSERT INTO `skip_list` (`id`, `ord`, `item`, `reason`) VALUES
  (1, 1, 'Kubernetes', 'You will not be asked at this level and it will cost you a week you do not have.'),
  (2, 2, 'Terraform', 'Infrastructure as code matters at scale. You are not at scale.'),
  (3, 3, 'Kafka', 'BullMQ on Redis teaches you the same queue concepts in a fraction of the time.'),
  (4, 4, 'Microservices', 'One well-structured monolith you can explain beats four services you cannot.'),
  (5, 5, 'GraphQL', 'REST is what the job postings ask for. Revisit only if a target company uses it.'),
  (6, 6, 'Redux', 'React context plus a small store covers everything you will build here.'),
  (7, 7, 'MongoDB', 'Your data is relational. Using a document store would be a wrong answer you have to defend.'),
  (8, 8, 'Bun and Deno', 'Interesting. Not hiring criteria. Node is what the postings say.'),
  (9, 9, 'Fine-tuning models', 'You are building on models, not making them. Applied AI roles want plumbing and evals.'),
  (10, 10, 'LeetCode contests', 'Timed contests train speed under a format you will not face. Patterns beat speed here.'),
  (11, 11, 'Blogging about learning', 'Ship the project. The project is the post.'),
  (12, 12, 'Another course purchase', 'You already own 100xDevs. Nothing else needs buying. See Part 7.'),
  (13, 13, 'Rewriting Project 1 in a new framework', 'Four projects at four difficulty levels beats one project rewritten four times.'),
  (14, 14, 'Competitive programming', 'Different skill, different reward curve, no overlap with the roles in Part 12.'),
  (15, 15, 'Certifications before Gate 4', 'No interviewer in this band asks. AWS SAA is optional and only after Gate 4.')
INSERT INTO `do_not_buy` (`id`, `ord`, `item`) VALUES
  (1, 1, 'Another Udemy course. You own 100xDevs and have not finished it.'),
  (2, 2, 'A DSA course. Striver A2Z is free and is the sheet Indian interviewers recognise.'),
  (3, 3, 'A resume review service. Part 15 has the template and the rules.'),
  (4, 4, 'LeetCode Premium. The free tier covers all 474 problems on the A2Z sheet.'),
  (5, 5, 'A mock interview package before Week 20. You would be paying to be told what you already know.'),
  (6, 6, 'Any AI certification. No role in Part 12 asks for one. Projects with eval numbers replace them.')
INSERT INTO `added_topics` (`id`, `ord`, `item`, `reason`) VALUES
  (1, 1, 'Cost accounting for LLM applications', 'Applied AI interviews ask what it costs per query. Almost no junior candidate has an answer.'),
  (2, 2, 'Idempotency', 'Retries are guaranteed. Idempotent handlers are the difference between a queue and a duplicate-charge incident.'),
  (3, 3, 'EXPLAIN ANALYZE and plan reading', 'One before-and-after number in a README is worth more than three extra features.'),
  (4, 4, 'Structured logging with request IDs', 'The first thing a backend team checks is whether you can debug production.'),
  (5, 5, 'Supply chain security', 'A03 is new and near the top of the 2025 list. Pinned actions and lockfile audits are cheap.'),
  (6, 6, 'Prompt injection through a retrieval corpus', 'Your RAG corpus is an attack surface. Most portfolio projects ignore this entirely.'),
  (7, 7, 'Rollback you have actually executed', 'Thirty seconds of screen capture. The most convincing artefact a junior can show.'),
  (8, 8, 'Reciprocal rank fusion', 'The simple, defensible way to combine dense and BM25 results.'),
  (9, 9, 'Node 26 migration decision', 'It lands inside this roadmap. Having a reasoned position is itself an interview answer.'),
  (10, 10, 'Reading other people’s code', 'Two working Sundays on n8n. Reading code is the skill that separates week one from week twelve on a real team.'),
  (11, 11, 'Forward Deployed Engineer case drills', 'A distinct interview format. Four of the ten Week 20 mocks are case studies for this reason.')
INSERT INTO `costs` (`id`, `ord`, `item`, `cost`, `note`) VALUES
  (1, 1, 'Everything in Parts 1 to 19 except the two lines below', 'Rs 0', 'Every course, book, lab and tool in this roadmap has a free tier that is sufficient. This is not a compromise; these are the best resources that exist.'),
  (2, 2, 'LLM API credit, Weeks 16 to 19', 'Rs 1,500', 'Unavoidable. Set a hard spend cap on the key on day one of the launch block, before you write a line of AI code.'),
  (3, 3, 'Domain name, optional', 'Rs 900 per year', 'You already own paisareality.com, devpilotx.com and value.codes. Use a subdomain. This line can be Rs 0.'),
  (4, 4, 'AWS Solutions Architect Associate, optional, after Gate 4 only', 'Rs 7,600', 'Not required by any role in Part 12. Consider only if a target employer names it in the posting.')
INSERT INTO `continuation` (`id`, `ord`, `kind`, `label`, `period`, `age_label`, `goal`, `detail`, `hours_text`) VALUES
  (1, 1, 'branch', 'A', 'February 2027 onward', '', 'Employed', 'Depth in one thing, plus whatever the job does not teach you', '2 to 3 on weekdays, 6 on Saturday'),
  (2, 2, 'branch', 'B', 'February 2027 onward', '', 'Not yet employed', 'Applications become the job: 4 h applications, 2 h DSA, 2 h build', 'Full 8 continues'),
  (3, 3, 'branch', 'C', 'February 2027 onward', '', 'Building your own thing', 'Ship something a stranger pays for before you call it a startup', 'Full 8, self directed'),
  (4, 4, 'bridge', 'February to March 2027', 'February to March 2027', '', '**Finish DSA 474.** Fifty nine problems remain. At 2 hours a day that is about six weeks.', '', ''),
  (5, 5, 'bridge', 'February to March 2027', 'February to March 2027', '', '**Keep the pipeline running.** Total target 200 to 400 applications, not 100.', '', ''),
  (6, 6, 'bridge', 'February to March 2027', 'February to March 2027', '', '**Two mock interviews per week.** Exponent Practice and interviewing.io are both in Part 7.', '', ''),
  (7, 7, 'bridge', 'February to March 2027', 'February to March 2027', '', '**Do not start a new project.** Deepen Tender Fit instead. A fifth shallow project is worth less than one project with real evaluation numbers.', '', ''),
  (8, 8, 'bridge', 'February to March 2027', 'February to March 2027', '', '**Write three things publicly.** One on the ITC Reclaim reconciliation logic, one on the Ragas numbers and what they revealed, one on the MCP server. These are what recruiters actually read.', '', ''),
  (9, 9, 'weekday', 'Depth: the one thing', '06:00 to 07:30', '', 'Depth: the one thing', '', '1.5'),
  (10, 10, 'weekday', 'The job', 'Work day', '', 'The job', '', '8 to 9'),
  (11, 11, 'weekday', 'Anki plus reading', '21:00 to 21:45', '', 'Anki plus reading', '', '0.75'),
  (12, 12, 'weekday', 'Build, write, open source', 'Saturday 09:00 to 15:00', '', 'Build, write, open source', '', '6'),
  (13, 13, 'weekday', 'Rest. Non negotiable.', 'Sunday', '', 'Rest. Non negotiable.', '', '0'),
  (14, 14, 'year', 'Year one', 'April 2027 to March 2028', 'age 24', 'stop being a junior. Own one service end to end in production.', '', ''),
  (15, 15, 'quarter', 'Q1', 'April 2027 to March 2028', 'age 24', 'Learn the codebase and the domain. Ask more questions than you answer. Ship small and often', '', ''),
  (16, 16, 'quarter', 'Q2', 'April 2027 to March 2028', 'age 24', 'Own one service or one significant feature end to end, including its on call', '', ''),
  (17, 17, 'quarter', 'Q3', 'April 2027 to March 2028', 'age 24', 'Lead one migration or one performance fix with a number attached: latency, cost, or error rate', '', ''),
  (18, 18, 'quarter', 'Q4', 'April 2027 to March 2028', 'age 24', 'Write it up publicly. Internal document minimum, blog post preferred', '', ''),
  (19, 19, 'year_detail', 'Year one', 'April 2027 to March 2028', 'age 24', '**Depth hours:** production RAG at real volume, evaluation pipelines, cost per query, prompt injection defence, agent termination conditions.', '', ''),
  (20, 20, 'year_detail', 'Year one', 'April 2027 to March 2028', 'age 24', '**Breadth hours:** real system design rather than the primer, PostgreSQL under load, distributed tracing, one cloud properly. The AWS Solutions Architect Associate at about Rs 7,600 is optional and only worth it if a target employer asks for it.', '', ''),
  (21, 21, 'year_detail', 'Year one', 'April 2027 to March 2028', 'age 24', '**Outside work:** one open source contribution a quarter, one written piece a month.', '', ''),
  (22, 22, 'year_detail', 'Year one', 'April 2027 to March 2028', 'age 24', '**Money:** save 40 to 50 per cent of take home if you are living at home. This is your runway and your New Zealand fund, in that order.', '', ''),
  (23, 23, 'year', 'Year two', '2028 to 2029', 'age 25 to 26', 'mid level. A title change or a company change.', '', ''),
  (24, 24, 'year_detail', 'Year two', '2028 to 2029', 'age 25 to 26', '**Plan the switch at 18 to 24 months, not 36.** In India the first to second job move is where compensation actually steps, typically 40 to 80 per cent, far more than any internal increment.', '', ''),
  (25, 25, 'year_detail', 'Year two', '2028 to 2029', 'age 25 to 26', 'Lead a piece of work with more than one engineer on it. Get design review authority. Own on call for something that matters.', '', ''),
  (26, 26, 'year_detail', 'Year two', '2028 to 2029', 'age 25 to 26', '**Start IELTS preparation this year.** Part 16 explains why this is not optional and why it was correctly deleted from the 21 week plan but must come back here.', '', ''),
  (27, 27, 'year', 'Year three', '2029 to 2030', 'age 26 to 27', 'three years verifiable experience, which is the New Zealand work visa skills threshold.', '', ''),
  (28, 28, 'year_detail', 'Year three', '2029 to 2030', 'age 26 to 27', 'Get the NZQA International Qualification Assessment on the BCA. **Start this early.** It takes months and the result can surprise you. See the risk note at the end of Part 16.', '', ''),
  (29, 29, 'year_detail', 'Year three', '2029 to 2030', 'age 26 to 27', 'Sit IELTS or an accepted equivalent.', '', ''),
  (30, 30, 'year_detail', 'Year three', '2029 to 2030', 'age 26 to 27', 'Begin applying to New Zealand accredited employers. Target NZD 100,000 or more, which clears the immigration wage threshold with room.', '', '')
INSERT INTO `nz_requirements` (`id`, `ord`, `requirement`, `detail`) VALUES
  (1, 1, 'Age', '55 or younger when you apply. You are 23 on your government ID and 25 by your actual date of birth. Not a constraint on either'),
  (2, 2, 'Job', 'Offer of, or already working in, a Green List Tier 1 job'),
  (3, 3, 'Employer', 'Must be an accredited employer'),
  (4, 4, 'Hours', 'Full time'),
  (5, 5, 'Term', 'Permanent, or fixed term of at least 12 months, or a contract of at least 6 months'),
  (6, 6, 'Pay', 'At least the rate specified for the Green List role, or the median wage where no rate is specified'),
  (7, 7, 'English', 'Required, and a **higher standard applies to skilled residence visas** than to other residence categories'),
  (8, 8, 'Health and character', 'Medicals and police certificates')
INSERT INTO `nz_facts` (`id`, `ord`, `group_key`, `label`, `value`, `caveat`) VALUES
