  (2, 2, 'wage', '1.5x median', 'NZD 52.50 per hour', 'about NZD 109,200'),
  (3, 3, 'wage', '2x median, Highly Paid Residence Visa', 'NZD 70.00 per hour', 'about NZD 145,600'),
  (4, 4, 'salary', 'levels.fyi, New Zealand, Aug 2026', 'Median total comp NZD 136,586. 25th 98,593. 75th 165,625. 90th about 201,000', 'Self reported, skews senior and skews large employers'),
  (5, 5, 'salary', 'levels.fyi, Auckland', 'Median total comp NZD 123,216', 'Self reported'),
  (6, 6, 'salary', 'PayScale, Software Engineer NZ, Jul 2026', 'Average base NZD 85,174. Median 85,000. 10th 62,000. 90th 123,000', '238 profiles, base only'),
  (7, 7, 'salary', 'PayScale, Full Stack Developer NZ, Jul 2026', 'Average base NZD 88,546', '36 profiles only, weak sample'),
  (8, 8, 'salary', 'Glassdoor, Wellington', 'NZD 99,000', 'Self reported'),
  (9, 9, 'salary', 'Top Auckland payers', 'Atlassian NZD 219,777. Canva NZD 179,321. Westpac NZD 168,215', 'levels.fyi')
INSERT INTO `nz_corrections` (`id`, `ord`, `title`, `body`) VALUES
  (1, 1, 'You do not need lots of money. You need a job offer.', 'Straight to Residence is employer led. The wage threshold is satisfied by the employer, not by your savings. Your direct costs are visa fees, medicals, police certificates, the English test, the NZQA assessment, flights, and roughly two months of living expenses on arrival. Realistically **NZD 8,000 to 15,000 for one person**, not lakhs of migration savings. The money that matters is the salary the job pays. The savings that matter are your runway between jobs, which Part 15 already tells you to build at 40 to 50 per cent of take home.'),
  (2, 2, 'You cannot skip the experience.', 'The work visa route into New Zealand requires, as a minimum skills threshold, at least three years of verifiable relevant work experience **or** a relevant NZQA Level 4 or higher qualification. Even where a degree satisfies it on paper, New Zealand employers hiring offshore at zero years of experience is rare. The realistic sequence is India first, then New Zealand at mid level. That is exactly what Part 15 builds.'),
  (3, 3, 'English is deferred, not deleted.', 'You asked me to remove the English block from the 21 week roadmap. That was the right call for an Indian job hunt in 2026 and it stays removed. But skilled residence visas require a demonstrably higher standard of English than other categories, and Immigration New Zealand extended English requirements to Skill Level 3 occupations from 1 June 2026. IELTS or an accepted equivalent becomes a hard requirement around 2029. **Part 15, Year two is where it re-enters the plan. Do not touch it before then.**')
