  (1, 1, '24 Jan 2027', '24', '26', '24 on ID, 26 actual', 'Gate 4. Roadmap complete'),
  (2, 2, 'Mar to Jun 2027', '24', '26', '24 on ID, 26 actual', 'First job in India'),
  (3, 3, '2027 to 2030', '24 to 27', '26 to 29', '24 to 27 on ID, 26 to 29 actual', 'Three years verifiable experience. One switch at 18 to 24 months'),
  (4, 4, '2029', '26', '28', '26 on ID, 28 actual', 'NZQA International Qualification Assessment. IELTS'),
  (5, 5, '2029 to 2030', '26 to 27', '28 to 29', '26 to 27 on ID, 28 to 29 actual', 'Apply to New Zealand accredited employers. Target NZD 100,000 plus'),
  (6, 6, '2030 to 2031', '27 to 28', '29 to 30', '27 to 28 on ID, 29 to 30 actual', 'Move. Straight to Residence on the offer, or work visa then residence'),
  (7, 7, '2032 to 2033', '29 to 30', '31 to 32', '29 to 30 on ID, 31 to 32 actual', 'Permanent Resident Visa, after 2 years holding residence and meeting the presence requirement')
